To manually benchmark hipDNN execution plans, you first validate and build the operation graph and execution plans. Then, determine the maximum workspace size required across all plans and allocate it using `hipMalloc`. You benchmark each plan using `hipEventRecord` and `hipEventElapsedTime` to measure execution time. After identifying the fastest plan, build and execute it. Here's a minimal code snippet:

```cpp
graph.validate();
graph.build_operation_graph(handle);
graph.create_execution_plans({HeuristicMode::FALLBACK});
graph.build_plans(BuildPlanPolicy::ALL);

auto plan_count = graph.get_execution_plan_count();

int64_t ws = 0;
for (int i = 0; i < plan_count; i++)
    ws = std::max(ws, graph.get_workspace_size_plan_at_index(i));
void* workspace;
hipMalloc(&workspace, ws);

hipEvent_t start, stop;
hipEventCreate(&start);
hipEventCreate(&stop);
std::vector<float> times(plan_count, 10.0f);

for (int i = 0; i < plan_count; i++) {
    auto err = graph.execute_plan_at_index(handle, variant_pack, workspace, i);
    if (err.is_bad()) continue;
    hipDeviceSynchronize();

    hipEventRecord(start, stream);
    for (int iter = 0; iter < 10; iter++)
        graph.execute_plan_at_index(handle, variant_pack, workspace, i);
    hipEventRecord(stop, stream);
    hipEventSynchronize(stop);

    float ms;
    hipEventElapsedTime(&ms, start, stop);
    times[i] = ms / 10.0f;
}

auto best = std::min_element(times.begin(), times.end());
auto idx = std::distance(times.begin(), best);

graph.build_plan_at_index(idx);
graph.execute(handle, variant_pack, workspace);
```

