A recommended approach is to use an `std::vector` along with `std::sort` and `std::unique` to eliminate duplicates. After sorting and deduplication, you can efficiently query the data using algorithms like `std::lower_bound` or `std::equal_range` for binary search operations.

Here is a minimal example:

```cpp
#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> data = {5, 3, 1, 3, 5, 9};

    // Sort and remove duplicates
    std::sort(data.begin(), data.end());
    auto last = std::unique(data.begin(), data.end());
    data.erase(last, data.end());

    // Example query using binary search
    int query = 3;
    auto it = std::lower_bound(data.begin(), data.end(), query);
    if (it != data.end() && *it == query) {
        std::cout << "Found " << query << std::endl;
    } else {
        std::cout << query << " not found" << std::endl;
    }

    return 0;
}
```

